29	P_AUDIO_COPY {"type":"object","statement":"第18章沈电脑保存两份未处理原带转录工作副本，来源是第4章停点以后及另一面正常监听；与第1章家中硬盘工作副本分开，缺带起首小段。","status":"active","cast":["沈禾","顾遥"],"custody":{"holder":"沈禾","location":"沈禾自用电脑","condition":"两份未处理转录保留空白杂音，未降噪拼剪，原带另盒自持"},"character_known":{"沈禾":"自己接线转录保存，缺起首，未比电脑旧片段。","顾遥":"协助核链路与守带，未接副本或原件。"},"evidence":[{"unit":18,"quote":"沈禾保存两份未处理的转录"}],"tags":[],"introduced_unit":18,"updated_unit":18}
30	I_AUDIO_ALIGN {"type":"fact","statement":"第19章沈在家交替三次比旧电脑请片段和18章原带转录，两遍完整句请长度不对，前面试请气音与两下背景轻响位置相近，倾向同一遍试读；属于局部比对及解释，非整带同日、剪者目录用意或日期证明。","status":"partial","cast":["沈禾"],"tags":["关联T_SIGNAL","关联T_TAPE","工作副本比较"],"character_known":{"沈禾":"亲做局部比对，知道吻合范围与不能推出部分；向周画听取范围而未播放。"},"evidence":[{"unit":19,"quote":"这让她更倾向于同一遍试读，却还不能替整盒带子写一个日期"}],"introduced_unit":19,"updated_unit":19}
31	O_INDEX_CONT {"type":"observation","statement":"第19章周手机显示自称昨午原册拍的两张工作照，沈看见续表页头航务杂存续表、书脊与前页破边、航务散页一袋移镇航运服务室及口信登记二册随袋，接收章压住小字；沈收照片而未见原册。","status":"active","cast":["沈禾","周砚"],"tags":["关联T_INDEX","续表照片"],"character_known":{"沈禾":"亲看并收工作照，不猜章下名，不将2013清点当传话日。","周砚":"出示自称原册工作照片，不以照片保证袋内材料齐。","唐穗":"只听沈述照片去向和口信二册，未看照。"},"evidence":[{"unit":19,"quote":"页头写“航务杂存续表”，书脊附近能见前页翻起的破边。"}],"introduced_unit":19,"updated_unit":19}
32	T_SERVICE_VISIT {"type":"thread","statement":"第19章沈依目录续表工作照片的镇航运服务室转存去向，唐提供现联系页号码，电话宋俭约第6日10:30查袋、11:30他需验窗；实际材料和接话人尚未见。","status":"resolved","cast":["沈禾","宋俭"],"tags":["关联T_SIGNAL","关联T_INDEX","口信登记"],"character_known":{"沈禾":"20亲到查袋见册行拍局部，原件宋收，知袋内余散页没展、不认完整；经宋联系邱约未访。；此前知情保留：亲电话获约及河街里旧办公院地址，9:58离站步行，未抵达。","宋俭":"20亲开柜取袋并收回；说明后来接管非当日收，不保齐。；此前知情保留：电话仅听清点年份袋名，未保证材料齐或接收箱灯。","唐穗":"给号码，未替服务室承诺接收物件。"},"evidence":[{"unit":19,"quote":"只约十点半来，十一点半他得带人验窗，晚了要另等。"},{"unit":20,"quote":"十点半进了旧办公院。"},{"unit":20,"quote":"袋里余下的散页还没展开"}],"introduced_unit":19,"updated_unit":20,"reader_known":"20已实际到服务室查现袋和两口信册，目标到访完成；原话另签、余散页完整性与历史接收链仍待核，另T_CONTACT/T_SIGNAL继续追踪。"}
33	O_MESSAGE_ROW {"type":"observation","statement":"第20章沈与宋在现航务袋二〇一二年封面口信册内见九月十七日十四点二十行：西埠四号来话转候船室交邱阿兰；旁注原话另签，上方浅锈夹痕、夹签位置空。2011另册封面可见，袋内余散页未展。该行没写原带那句话，录音没报此日，不确认与录音是同一事件或确认最终接收人。","status":"active","cast":["沈禾","宋俭"],"tags":["关联T_SIGNAL","关联T_INDEX","口信登记行"],"character_known":{"沈禾":"亲读册封与该行、空夹位并获准拍照，日期只抄新行不配声音；未知另签和接话去向。","宋俭":"在场看行并允许局部照，不认邱笔迹与当日历史。"},"evidence":[{"unit":20,"quote":"九月十七日，十四点二十。西埠四号来话，转候船室，交邱阿兰。"},{"unit":20,"quote":"旁边添着小字：“原话另签。”"},{"unit":20,"quote":"她将日期抄在新的一行，和声音的日期隔开。"}],"introduced_unit":20,"updated_unit":20}
34	P_SERVICE_BAG {"type":"object","statement":"第20章服务室宋从柜中取的现布袋，标2013年6月清理航务杂存，现有2011/2012口信二册及未展开的余散页，扎绳换过且留褪色旧线，历史完整性待核。","status":"active","cast":["宋俭","沈禾"],"custody":{"holder":"宋俭","location":"镇航运服务室靠墙柜中层，袋口系好、柜已锁","condition":"宋亲取两册供读后将衬板与两册收回袋并锁回柜；2012册当前夹签位空，余散页未展，无原物交沈"},"character_known":{"宋俭":"自己现管实取收，后来接管不保证全袋完整。","沈禾":"实见现袋现册和宋收回，只带工作照，不领原件。"},"evidence":[{"unit":20,"quote":"宋俭自己合册，连衬板与另一本收回布袋，系好袋口放回柜中，锁上。"}],"tags":[],"introduced_unit":20,"updated_unit":20}
35	T_CONTACT {"type":"thread","statement":"第20章口信行出现交邱阿兰，宋仅忆其候船室接电话而不认该笔或当日；现联系本致电、沈接听说明询西埠转候船室口信未先念录音，约第6日16点后河街缝纫铺门边蓝围裙。尚未当面查访、未确认经手或最终接收。","status":"pending","cast":["沈禾","宋俭","邱阿兰"],"tags":["关联T_SIGNAL","关联O_MESSAGE_ROW","查访约"],"character_known":{"沈禾":"亲通话获16点后地点约，没被确认历史；不会把交邱当最终收件。","宋俭":"自称记邱接过电话，实际联系促约，不认当日该笔。","邱阿兰":"只获沈岚女儿问西埠转候船室口信的来意，未听录音或被念登记行，约四点后见尚未发生。"},"evidence":[{"unit":20,"quote":"四点后你来河街缝纫铺，门边挂蓝围裙的。别现在来等。"}],"introduced_unit":20,"updated_unit":20}
36	T_ARCHIVE {"type":"thread","statement":"第20章沈给宋看当次原箱照片说明东侧发现点、首日独开未拍及归属未核，宋只示里间桌角、称小箱明早问负责人且须核谁物谁管，长灯不接；没有接收或搬物。","status":"pending","cast":["沈禾","宋俭","唐穗"],"tags":["关联P_BOX","关联T_LAMP","接收去向"],"character_known":{"沈禾":"亲看桌角干地但今天窗框占位，明早只约问负责人，接收人未定；长灯不接，电话告唐不拆。","宋俭":"只看箱照获发现点和权属未明，不接原箱长灯、不许沈把候问写成接收。","唐穗":"仅电话听沈说不收长灯、小箱明早问负责人，无接收当前不能拆，未获邱及日期。"},"evidence":[{"unit":20,"quote":"她把桌角的位置记下，只写候问，没给它添上接收人。"}],"introduced_unit":20,"updated_unit":20}

